import { isUndefined } from 'lodash-es';

import { DEFAULT_MARKER_COLOR } from '../../core/components/annotations-atoms/constants.js';
import { IndicatorsDisplay } from '../../core/components/annotations-atoms/types/indicator.js';
import { MarkerInteractionState } from '../../core/components/annotations-atoms/types/marker.js';
import { buildMarkerState } from '../../core/components/annotations-timeseries/functions/build-marker-state.js';
import { markerGroupKey } from '../../core/components/annotations-timeseries/functions/marker-group-key.js';
import { AnnotationGroup } from '../../core/components/annotations-timeseries/types/annotations.js';
import { SelectionState as AnnotationsTimeseriesSelectionState } from '../../core/components/annotations-timeseries/types/state.js';
import { TimeseriesAnnotationsTrackRendererProps } from '../context/TimeseriesChartAnnotationsConfig.context.js';
import { IndicatorData } from '../types/indicators.js';

const isAlwaysShown = (
  showIndicators?: IndicatorsDisplay,
  indicatorsDisplay?: IndicatorsDisplay,
) => showIndicators === 'always' || indicatorsDisplay === 'always';

const isShownByInteraction = (
  data: AnnotationGroup[] | undefined,
  markerId: string,
  indicatorsDisplay: IndicatorsDisplay | undefined,
) =>
  indicatorsDisplay !== 'never' &&
  data &&
  data.map(({ start, end }) => markerGroupKey(start, end)).includes(markerId);

function buildIndicator(
  color: string,
  selection: AnnotationsTimeseriesSelectionState,
  markerId: string,
  start: Date,
  end: Date | undefined,
  currentTrack: number,
  priority?: number,
): IndicatorData {
  const isListHovered = selection.hoverGroupListKey === markerId;
  let state: MarkerInteractionState = 'default';
  if (currentTrack === selection.hoveredTrack) {
    state = buildMarkerState(selection, markerId, isListHovered);
  }

  return {
    end,
    start,
    color,
    state,
    priority,
  };
}

const isAlwaysHidden = (
  markerIndicatorVisibility?: IndicatorsDisplay,
  trackIndicatorsVisibility?: IndicatorsDisplay,
) =>
  markerIndicatorVisibility === 'never' ||
  (isUndefined(markerIndicatorVisibility) &&
    trackIndicatorsVisibility === 'never');

export const getShownIndicators = (
  tracks: TimeseriesAnnotationsTrackRendererProps[],
  selection: AnnotationsTimeseriesSelectionState,
): IndicatorData[][] =>
  tracks.map(
    (currentTrack: TimeseriesAnnotationsTrackRendererProps, trackIndex) =>
      currentTrack.markers.reduce((indicators, currentMarker) => {
        const {
          indicatorsDisplay: trackIndicatorsVisibility,
          color: trackColor,
        } = currentTrack;
        const {
          color: markerColor,
          data: { start: markerStart, end: markerEnd },
          indicatorsDisplay: markerIndicatorVisibility,
          priority,
        } = currentMarker;

        if (
          isAlwaysHidden(markerIndicatorVisibility, trackIndicatorsVisibility)
        ) {
          return indicators;
        }
        const markerId = markerGroupKey(markerStart, markerEnd);
        const displayIndicator =
          isAlwaysShown(markerIndicatorVisibility, trackIndicatorsVisibility) ||
          isShownByInteraction(
            selection.data,
            markerId,
            markerIndicatorVisibility,
          );

        if (displayIndicator) {
          const color = markerColor || trackColor || DEFAULT_MARKER_COLOR;
          const indicator = buildIndicator(
            color,
            selection,
            markerId,
            markerStart,
            markerEnd,
            trackIndex,
            priority,
          );

          return [...indicators, indicator];
        }

        return indicators;
      }, [] as IndicatorData[]),
    [] as IndicatorData[],
  );
